    private static final Map<String, Schema> BY_NAME =
            ALL.stream().collect(Collectors.toUnmodifiableMap(Schema::fullName, Function.identity()));

    public static Schema get(String fullName) {
        Schema schema = BY_NAME.get(fullName);
        if (schema == null) {
            throw new IllegalArgumentException("Unknown operator schema: " + fullName);
        }
        return schema;
    }
